"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[28913],{28913:function(e){e.exports=JSON.parse('{"content":"\\n## Efficiently Transfer Docker Images over SSH without a Registry\\nDocker images can be moved using only ssh without a separate registry.\\n\\n### Principle\\nDocker images can be saved as files and reloaded.\\nUsually, this is done in two steps:\\n- <b>Source :</b> Extract the image to a tar file with docker save\\n- <b>Destination :</b> Copy the file and then register the image with docker load\\n\\n### Command\\nUsing the ssh compression option and pipeline, you can transfer images more quickly and concisely.\\n```bash\\n{\\n    \\"title\\": \\"Efficiently Transfer Docker Images over SSH without a Registry\\"\\n}\\n---\\n$ ssh -C user@ipaddress \\"docker save <docker image>\\" | docker load\\n```"}')}}]);